//! The per-axis attributes (Label, Symbol, Unit, Format, Digits, Direction,
//! Top and Bottom) of every Frame class, through the `Frame` trait, checked
//! against the C library.
//!
//! `frame_axis_oracle/cases.rs` is generated by
//! `tools/oracle_fixtures/frame_axis_attrs_probe.c`, which builds one object
//! of each class, sets one attribute on its first or last axis and reads
//! every attribute of every axis back through C's `astGetLabel` family. It
//! pins each class's defaults, how a compound Frame routes an axis to its
//! component and lends it its Digits, and what the components, a FrameSet's
//! current Frame and a Region's Frame then report ("inner1", "inner2").

// Generated; formatted by its generator rather than rustfmt.
#[rustfmt::skip]
#[path = "frame_axis_oracle/cases.rs"]
mod cases;

use cases::V;

use starlink_ast::frames::{
    BasicFrameBuilder, CmpFrame, DSBSpecFrame, DynFrame, FluxFrame, FluxSystem, Frame, FrameSet,
    SkyFrame, SkySystem, SpecFluxFrame, SpecFrame, SpecSystem, TimeFrame, TimeSystem,
};
use starlink_ast::regions::{CircleBuilder, Region};

fn make(class: &str) -> DynFrame {
    match class {
        "Frame" => Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        "SkyFrame" => Box::new(SkyFrame::new(SkySystem::Icrs)),
        "SpecFrame" => Box::new(SpecFrame::new(SpecSystem::Wavelen)),
        "DSBSpecFrame" => Box::new(DSBSpecFrame::new(SpecSystem::Wavelen)),
        "TimeFrame" => Box::new(TimeFrame::new(TimeSystem::Mjd)),
        "FluxFrame" => Box::new(FluxFrame::new(FluxSystem::FluxDen)),
        "SpecFluxFrame" => Box::new(SpecFluxFrame::new(
            SpecFrame::new(SpecSystem::Wavelen),
            FluxFrame::new(FluxSystem::FluxDen),
        )),
        "CmpFrame" => Box::new(CmpFrame::new(
            Box::new(SkyFrame::new(SkySystem::Icrs)),
            Box::new(SpecFrame::new(SpecSystem::Wavelen)),
        )),
        "PlainCmpFrame" => Box::new(CmpFrame::new(
            Box::new(BasicFrameBuilder::new(1).build().unwrap()),
            Box::new(BasicFrameBuilder::new(2).build().unwrap()),
        )),
        "FrameSet" => Box::new(FrameSet::new(Box::new(SkyFrame::new(SkySystem::Icrs)))),
        "Circle" => Box::new(
            CircleBuilder::new(SkyFrame::new(SkySystem::Icrs), vec![0.0, 0.0])
                .unwrap()
                .radius(0.01)
                .build()
                .unwrap(),
        ),
        other => panic!("unexpected class {other}"),
    }
}

/// The Frames whose attributes show the effect of setting one on `f`.
fn inner(class: &str, f: &dyn Frame) -> Vec<DynFrame> {
    let any = f.as_any();
    match class {
        "CmpFrame" | "PlainCmpFrame" => {
            let c = any.downcast_ref::<CmpFrame>().unwrap();
            vec![c.frame1().snapshot(), c.frame2().snapshot()]
        }
        "SpecFluxFrame" => {
            let c = any.downcast_ref::<SpecFluxFrame>().unwrap();
            vec![
                Box::new(c.spec_frame().clone()),
                Box::new(c.flux_frame().clone()),
            ]
        }
        "FrameSet" => vec![any.downcast_ref::<FrameSet>().unwrap().current().snapshot()],
        "Circle" => vec![
            any.downcast_ref::<starlink_ast::regions::Circle>()
                .unwrap()
                .get_region_frame(),
        ],
        _ => Vec::new(),
    }
}

/// Split `"Label(2)"` into its name and axis.
fn split(attr: &str) -> (&str, usize) {
    let (name, rest) = attr.split_once('(').unwrap();
    (name, rest.trim_end_matches(')').parse().unwrap())
}

fn apply(f: &mut dyn Frame, setting: &str) {
    let Some((attr, value)) = setting.split_once('=') else {
        return;
    };
    if attr == "Digits" {
        f.set_digits(value.parse().unwrap()).unwrap();
        return;
    }
    let (name, axis) = split(attr);
    match name {
        "Label" => f.set_label(axis, value),
        "Symbol" => f.set_symbol(axis, value),
        "Unit" => f.set_unit(axis, value),
        "Format" => f.set_format_str(axis, value),
        "Digits" => f.set_axis_digits(axis, value.parse().unwrap()),
        "Direction" => f.set_direction(axis, value != "0"),
        "Top" => f.set_top(axis, value.parse().unwrap()),
        "Bottom" => f.set_bottom(axis, value.parse().unwrap()),
        other => panic!("unexpected setting {other}"),
    }
    .unwrap();
}

fn value(f: &dyn Frame, attr: &str) -> (V, bool) {
    let s = |v: String| V::S(Box::leak(v.into_boxed_str()));
    let (name, axis) = split(attr);
    match name {
        "Label" => (s(f.label(axis).unwrap()), f.test_label(axis).unwrap()),
        "Symbol" => (s(f.symbol(axis).unwrap()), f.test_symbol(axis).unwrap()),
        "Unit" => (s(f.unit(axis).unwrap()), f.test_unit(axis).unwrap()),
        "Format" => (
            s(f.format_str(axis).unwrap()),
            f.test_format_str(axis).unwrap(),
        ),
        "Digits" => (
            V::I(f.axis_digits(axis).unwrap()),
            f.test_axis_digits(axis).unwrap(),
        ),
        "Direction" => (
            V::I(i32::from(f.direction(axis).unwrap())),
            f.test_direction(axis).unwrap(),
        ),
        "Top" => (V::D(f.top(axis).unwrap()), f.test_top(axis).unwrap()),
        "Bottom" => (V::D(f.bottom(axis).unwrap()), f.test_bottom(axis).unwrap()),
        other => panic!("unexpected attribute {other}"),
    }
}

#[test]
fn every_class_matches_the_c_library() {
    let mut failures = Vec::new();
    let mut last: Option<(&str, &str)> = None;
    let mut objects: Option<(DynFrame, Vec<DynFrame>)> = None;
    for &(class, setting, whose, attr, expected, expected_test) in cases::CASES {
        if last != Some((class, setting)) {
            let mut f = make(class);
            apply(f.as_mut(), setting);
            let i = inner(class, f.as_ref());
            objects = Some((f, i));
            last = Some((class, setting));
        }
        let (f, i) = objects.as_ref().unwrap();
        let target: &dyn Frame = match whose {
            "self" => f.as_ref(),
            "inner1" => i[0].as_ref(),
            _ => i[1].as_ref(),
        };
        let (got, got_test) = value(target, attr);
        if got != expected || got_test != expected_test {
            failures.push(format!(
                "{class} {setting:?} {whose} {attr}: got {got:?} test {got_test}, C gives {expected:?} test {expected_test}"
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} cases differ:\n{}",
        failures.len(),
        cases::CASES.len(),
        failures.join("\n")
    );
}

/// An axis index out of range is an error, as C's `astValidateAxis` makes it.
#[test]
fn an_axis_out_of_range_is_an_error() {
    for class in [
        "Frame",
        "SkyFrame",
        "SpecFrame",
        "TimeFrame",
        "CmpFrame",
        "FrameSet",
    ] {
        let mut f = make(class);
        let n = f.naxes();
        assert!(f.label(0).is_err(), "{class}");
        assert!(f.label(n + 1).is_err(), "{class}");
        assert!(f.set_top(n + 1, 1.0).is_err(), "{class}");
    }
}
